insert into public.tips (id, unit_id, title_en, body_md, status) values
  ('c5ccfebf-abb5-5c69-b2fb-f5a49cdb5788', 'dc485e04-124e-516d-9061-98a2d00f4d57', 'Asking with the present', 'A porteño asks with a plain question in the present: **¿me pasás la sal?**, **¿me ayudás?** — the *can you* is in the tone. **¿Podrías…?** is the extra-polite version.', 'draft'),
  ('0a0c6336-f327-5f98-83ba-2d0a95f6e002', 'dc485e04-124e-516d-9061-98a2d00f4d57', 'Ayudame', 'With a vos command the pronoun joins the end: **ayudame**, **alcanzame** — *help me*, *hand me*.', 'draft'),
  ('7fc50a6b-b755-5883-a742-eb3e04e4df87', 'afdaff40-37c8-56af-ae39-78f1ed48e97e', 'Tengo que, hay que', '**Tengo que laburar** is *I have to work*; **hay que** is the same for everyone: **hay que sacar la basura** — *the rubbish has to go out*.', 'draft'),
  ('1d2ec980-0806-5da8-bbf4-6621d289bcb9', 'afdaff40-37c8-56af-ae39-78f1ed48e97e', 'No hace falta', '**No hace falta** — *there''s no need*. **Conviene** is the advice: **conviene ir temprano** — *it''s best to go early*.', 'draft'),
  ('632ffd1b-e406-5c33-ae55-84874e2345f3', 'e7976a3a-80b3-505d-abc8-858bd6a92a90', '¿A cuánto está?', 'At the verdulería the price moves, so it''s **¿a cuánto está el kilo?** — *how much is it a kilo today?* You buy **un kilo**, **medio kilo** or **una docena**.', 'draft'),
  ('31b1cddf-37d2-5f9f-88fb-1c86fdda5c9c', 'e7976a3a-80b3-505d-abc8-858bd6a92a90', 'Dame', 'Nobody says *quisiera*: **dame un kilo de papas** — *give me a kilo of potatoes* — is polite enough with a *por favor*.', 'draft'),
  ('4e8246f2-31a4-5303-97f3-80f702ceb6f8', 'a921ed27-35b4-5222-9699-d8dd343c1f79', 'El celu', 'The phone is **el celu** (short for *celular*). **Me quedé sin batería** — *my battery died*; **se cortó** — *it cut out*; **mandame la ubicación** — *send me your location*.', 'draft'),
  ('301acde2-7437-5461-8414-6fb73db5b2cc', 'a921ed27-35b4-5222-9699-d8dd343c1f79', 'La SUBE', 'The card for the bus and the subte is **la SUBE**, and you **cargás** it at a kiosco — the same verb as charging a phone.', 'draft'),
  ('5aa4695d-1066-51a2-8216-9f8188a3c7de', '776b15fe-c6a5-5aae-8876-404d392e0546', 'Te lo, se lo', 'Two pronouns go person first, thing second: **te lo devuelvo** — *I''ll give it back to you*. *Le lo* never happens: it turns into **se lo**.', 'draft'),
  ('483431c0-946a-5b0b-8aed-14fb9fd5a2cb', '776b15fe-c6a5-5aae-8876-404d392e0546', 'Dejar', '**Dejame las llaves** — *leave me the keys*; **te dejo** — *I''ll leave you (to it)*, the porteño way of hanging up.', 'draft'),
  ('9cfec53b-7ae4-5c4a-9a0c-768b041ea780', 'd585de30-5927-5cbf-a88a-fc998547f793', 'Conseguir', '**Conseguí laburo** — *I got a job*. *Conseguir* is the porteño verb for getting anything that took effort: a *turno*, a table, a flat.', 'draft'),
  ('62b08ac0-383b-5a9f-9f1e-da41a2458c2a', 'd585de30-5927-5cbf-a88a-fc998547f793', 'Home office', 'Working from home is **hacer home office**, in English, and said the Spanish way.', 'draft'),
  ('dbb9fb4d-69cd-5b88-9d73-7d35bd390442', '770b6d5f-bd8c-5c17-a05f-4721faaa1706', 'Salir con', '**Estoy saliendo con alguien** — *I''m seeing someone*. When it ends, porteños **cortan**: **cortamos** — *we broke up*.', 'draft'),
  ('e73a1f00-3237-5fcb-a397-8dbe426556e7', '770b6d5f-bd8c-5c17-a05f-4721faaa1706', 'Alguien, nadie', '**Alguien** is *someone*, **nadie** is *nobody* — and Spanish keeps the *no* as well: **no vino nadie**.', 'draft'),
  ('5a7cee6d-5d77-55df-a22b-86d97d266f8c', '3dd370c2-01fe-54ba-95fc-3c5ef1637eb0', 'The future that guesses', 'For plans porteños say *voy a*. The future tense is for **guessing**: **¿dónde estará?** — *where can he be?*; **estará en el laburo** — *he''s probably at work*.', 'draft'),
  ('6f3c143b-2af0-5c70-b9e2-7435c2b347d4', '3dd370c2-01fe-54ba-95fc-3c5ef1637eb0', 'Será', '**¿Qué hora será?** — *I wonder what time it is*. **Será** on its own shrugs: *could be*.', 'draft'),
  ('1a8b45ec-c528-5164-9c7c-bb147aad29d0', '5ec6a727-4a91-5545-9e35-7f858d66ced1', 'Me siento', '**Me siento mal** — *I feel ill*; **¿cómo te sentís?** — *how do you feel?* On its own, **lo siento** is *I''m sorry*.', 'draft'),
  ('f8060d63-4a7a-541b-8eba-bf97588eae8b', '5ec6a727-4a91-5545-9e35-7f858d66ced1', 'La obra social', 'Your health insurance is your **obra social**; the doctor writes a **receta** and you take the **pastillas** **cada ocho horas**.', 'draft'),
  ('e8975dc4-db27-5349-91a4-dd07310d9224', '6ec21cf5-83ce-55f4-a07c-355a8fb995bb', 'Te debo una', '**Te debo una** — *I owe you one*. The answer is **de nada**, or, more porteño, **no pasa nada**.', 'draft'),
  ('85eeb729-9ee3-5ef6-a492-6eadc3ca5fdf', '6ec21cf5-83ce-55f4-a07c-355a8fb995bb', 'Un montón', '**Gracias por todo**, **mil gracias**, **gracias un montón** — the thanks gets bigger, the grammar doesn''t change.', 'draft')
